// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeFactorizedQuoteTest.edge;
import static org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeFactorizedQuoteTest.row;

import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeFanOutFactsTest.StatsSource;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativePackedFtreeQuote.Site;
import org.junit.jupiter.api.Test;

/**
 * The packed f-tree is quoted as its runtime works: roots are enumerated once, every tree edge is bound once per parent
 * lane and its neighbours copied as lanes, cycle-closing edges are intersected per candidate, lanes are packed and
 * counted once, and only a row consumer pays per logical row while an aggregate pays per demanded lane.
 */
class LmdbNativePackedFtreeQuoteTest {

	private static final long P1 = 1L, P2 = 2L, P = 7L;
	private static final int S = 0, A = 1, B = 2;

	private static StatsSource star(boolean served) {
		return new StatsSource(100_000L).predicate(P1, 3D, 3_000L).predicate(P2, 3D, 3_000L).adjacencyServed(served);
	}

	private static LmdbNativePackedFtree.Plan starPlan(RowState row) {
		MultiJoinPlan join = new MultiJoinPlan(new PatternPlan[] { edge(S, P1, A, 9_000D), edge(S, P2, B, 9_000D) },
				new MaskedFilter[0]);
		LmdbNativePackedFtree.Plan plan = LmdbNativePackedFtree.Planner.plan(join, row, new int[] { S, A, B });
		assertThat(plan).isNotNull();
		assertThat(plan.root.slot).isEqualTo(S);
		return plan;
	}

	@Test
	void aServedEdgeIsBoundOncePerParentLaneAndItsNeighboursCopied() {
		RowState row = row(star(true));
		LmdbNativeCostVector quote = LmdbNativePackedFtreeQuote.quote(starPlan(row), row, Site.ROWS, 0L, 27_000D)
				.total();
		// the root walks its 3000 adjacency keys; each edge binds once per root lane and copies 3 neighbours
		assertThat(quote.expected(Feature.INDEX_SEEK)).isEqualTo(6_000D);
		assertThat(quote.expected(Feature.SCANNED_ROW)).isEqualTo(3_000D + 18_000D);
		assertThat(quote.expected(Feature.DECODED_ROW)).isZero();
		// every lane is packed once and counted once: 3000 roots + 9000 + 9000 lanes
		assertThat(quote.expected(Feature.BATCH_ROW)).isEqualTo(2D * 21_000D);
		// a row consumer enumerates every logical row
		assertThat(quote.expected(Feature.GENERATED_ROW)).isEqualTo(27_000D);
		// one chunk per 1024 roots
		assertThat(quote.expected(Feature.OPEN)).isEqualTo(3D);
	}

	@Test
	void theAggregateSiteUpdatesDemandedLanesAndGeneratesNoRow() {
		RowState row = row(star(true));
		LmdbNativeCostVector quote = LmdbNativePackedFtreeQuote
				.quote(starPlan(row), row, Site.AGGREGATE, 1L << A, 27_000D)
				.total();
		assertThat(quote.expected(Feature.GENERATED_ROW)).isZero();
		// COUNT(DISTINCT ?a): one update per lane of ?a (9000), none per joined row (27000)
		assertThat(quote.expected(Feature.GROUP_UPDATE)).isEqualTo(9_000D);
	}

	@Test
	void anUnservedEdgeIsProbedInTheLmdbIndexOncePerParentLane() {
		RowState row = row(star(false));
		LmdbNativeCostVector quote = LmdbNativePackedFtreeQuote.quote(starPlan(row), row, Site.ROWS, 0L, 27_000D)
				.total();
		LmdbNativeCostVector scan = LmdbNativeCostVectors.pattern(edge(S, P1, A, 9_000D), row, 0L);
		LmdbNativeCostVector probe = LmdbNativeCostVectors.pattern(edge(S, P2, B, 9_000D), row, 1L << S);
		// the root scans its seed pattern (3000 distinct keys among 9000 rows); each edge probes once per root lane
		assertThat(quote.expected(Feature.INDEX_SEEK))
				.isEqualTo(scan.expected(Feature.INDEX_SEEK) + 2D * 3_000D * probe.expected(Feature.INDEX_SEEK));
		assertThat(quote.expected(Feature.DECODED_ROW))
				.isEqualTo(scan.expected(Feature.DECODED_ROW) + 2D * 3_000D * probe.expected(Feature.DECODED_ROW));
		assertThat(quote.expected(Feature.BATCH_ROW)).isEqualTo(2D * 21_000D);
		// every unserved lane opens a store cursor of its own
		assertThat(quote.expected(Feature.BRANCH_OPEN)).isEqualTo(2D * 3_000D);
	}

	@Test
	void aCycleClosingEdgeIsIntersectedPerPrimaryNeighbour() {
		StatsSource source = new StatsSource(100_000L).predicate(P, 3D, 3_000L)
				.predicateByObject(P, 3D, 3_000L)
				.adjacencyServed(true);
		RowState row = row(source);
		MultiJoinPlan join = new MultiJoinPlan(
				new PatternPlan[] { edge(S, P, A, 9_000D), edge(A, P, B, 9_000D), edge(B, P, S, 9_000D) },
				new MaskedFilter[0]);
		LmdbNativePackedFtree.Plan plan = LmdbNativePackedFtree.Planner.plan(join, row, new int[] { S, A, B });
		assertThat(plan).isNotNull();
		LmdbNativeCostVector quote = LmdbNativePackedFtreeQuote.quote(plan, row, Site.ROWS, 0L, 27D).total();
		// 3000 roots and 9000 second-level lanes; the closing edge binds once per second-level lane and the
		// intersection tests each of the 27000 third-level candidates, of which one in a thousand (3 / 3000) survives
		assertThat(quote.expected(Feature.INDEX_SEEK)).isEqualTo(3_000D + 9_000D + 9_000D);
		assertThat(quote.expected(Feature.MEMBERSHIP_TEST)).isEqualTo(27_000D);
		assertThat(quote.expected(Feature.BATCH_ROW)).isEqualTo(2D * (3_000D + 9_000D + 27D));
	}
}
